stepxmp.pre:
chapter > title {
    bookmark-level: 1;
}

section > title {
    bookmark-level: 2;
}

chapter:first-of-type > title {
    -cssmedia-toc-divider: "Chapters";
}

appendix:first-of-type > title {
    -cssmedia-toc-divider: "Appendixes";
}

@-cssmedia-toc-divider {
    font-weight: bold;
    margin-top: 8pt;
}
